      front: "What are callbacks and what is 'callback hell'?",
      back: "Callbacks are functions passed as arguments to be executed later. Callback hell (pyramid of doom) occurs when multiple nested callbacks make code hard to read and maintain.\n\nExample:\n```javascript\n// Basic callback example\nfunction fetchData(callback) {\n  setTimeout(() => {\n    callback('Data received');\n  }, 1000);\n}\n\nfetchData((result) => {\n  console.log(result); // 'Data received' after 1 second\n});\n\n// Callback hell example\nfunction getUser(userId, callback) {\n  setTimeout(() => callback({id: userId, name: 'John'}), 100);\n}\n\nfunction getPosts(userId, callback) {\n  setTimeout(() => callback(['Post1', 'Post2']), 200);\n}\n\nfunction getComments(postId, callback) {\n  setTimeout(() => callback(['Great!', 'Thanks']), 300);\n}\n\n// Nested callbacks - hard to read and maintain\ngetUser(1, (user) => {\n  console.log('User:', user.name);\n  getPosts(user.id, (posts) => {\n    console.log('Posts:', posts);\n    getComments(posts[0], (comments) => {\n      console.log('Comments:', comments);\n      // More nested callbacks...\n    });\n  });\n});\n```",
