      front: 'How do Promises work and what are their states?',
      back: "Promises represent eventual completion of asynchronous operations. They have three states: pending, fulfilled, and rejected. Promises help avoid callback hell.\n\nExample:\n```javascript\n// Creating a Promise\nconst myPromise = new Promise((resolve, reject) => {\n  // Async operation\n  setTimeout(() => {\n    const success = Math.random() > 0.5;\n    if (success) {\n      resolve('Operation successful!');\n    } else {\n      reject(new Error('Operation failed!'));\n    }\n  }, 1000);\n});\n\n// Using a Promise\nmyPromise\n  .then((result) => {\n    console.log('Success:', result);\n    return result.toUpperCase();\n  })\n  .then((upperResult) => {\n    console.log('Transformed:', upperResult);\n  })\n  .catch((error) => {\n    console.error('Error:', error.message);\n  })\n  .finally(() => {\n    console.log('Cleanup - always runs');\n  });\n\n// Promise states example\nconst pendingPromise = new Promise(() => {\n  // Never resolves or rejects\n});\nconsole.log(pendingPromise); // Promise {<pending>}\n\nconst fulfilledPromise = Promise.resolve('Immediate value');\nconsole.log(fulfilledPromise); // Promise {<fulfilled>: 'Immediate value'}\n\nconst rejectedPromise = Promise.reject(new Error('Immediate rejection'));\nrejectedPromise.catch(() => {}); // Prevent unhandled rejection\n\n// Promise static methods\nPromise.all([\n  Promise.resolve('Result 1'),\n  Promise.resolve('Result 2'),\n  Promise.resolve('Result 3')\n])\n  .then((results) => {\n    console.log('All resolved:', results); // ['Result 1', 'Result 2', 'Result 3']\n  });\n\nPromise.race([\n  new Promise(resolve => setTimeout(() => resolve('Fast'), 100)),\n  new Promise(resolve => setTimeout(() => resolve('Slow'), 500))\n])\n  .then((result) => {\n    console.log('Winner:', result); // 'Fast'\n  });\n```",
