      front: 'What is async/await and how does it simplify Promise handling?',
      back: "async/await is syntactic sugar over Promises that makes asynchronous code look synchronous. async functions always return Promises, and await pauses execution until a Promise settles.\n\nExample:\n```javascript\n// Basic async/await\nasync function fetchUserData() {\n  try {\n    const response = await fetch('https://api.example.com/user');\n    const user = await response.json();\n    console.log('User:', user);\n    return user;\n  } catch (error) {\n    console.error('Failed to fetch user:', error);\n    throw error;\n  } finally {\n    console.log('Fetch attempt completed');\n  }\n}\n\n// Using the async function\nfetchUserData()\n  .then(user => console.log('Got user:', user))\n  .catch(error => console.error('Error:', error));\n\n// Multiple await example\nasync function processData() {\n  const user = await getUser(1);\n  const posts = await getPosts(user.id);\n  const comments = await getComments(posts[0].id);\n  return { user, posts, comments };\n}\n\n// Parallel execution with Promise.all\nasync function fetchAllData() {\n  const [user, posts, settings] = await Promise.all([\n    getUser(1),\n    getPosts(1),\n    getSettings(1)\n  ]);\n  return { user, posts, settings };\n}\n\n// Error handling patterns\nasync function safeOperation() {\n  // Option 1: try/catch\n  try {\n    return await riskyOperation();\n  } catch (error) {\n    return defaultValue;\n  }\n  \n  // Option 2: .catch() on the Promise\n  const result = await riskyOperation().catch(() => defaultValue);\n  return result;\n}\n\n// Async arrow functions\nconst fetchData = async (url) => {\n  const response = await fetch(url);\n  return response.json();\n};\n\n// Async functions in array methods\nasync function processUsers(userIds) {\n  const users = await Promise.all(\n    userIds.map(async (id) => {\n      const user = await getUser(id);\n      return transformUser(user);\n    })\n  );\n  return users;\n}\n```",
