      front:
        'How do Promise.all(), Promise.race(), Promise.allSettled(), and Promise.any() differ?',
      back: "These Promise combiners handle multiple Promises differently: all() waits for all, race() for first settled, allSettled() for all settled, and any() for first fulfilled.\n\nExample:\n```javascript\n// Promise.all() - all must succeed\nconst promises1 = [\n  Promise.resolve('Result 1'),\n  Promise.resolve('Result 2'),\n  Promise.resolve('Result 3')\n];\n\nPromise.all(promises1)\n  .then(results => {\n    console.log('All succeeded:', results);\n    // ['Result 1', 'Result 2', 'Result 3']\n  })\n  .catch(error => {\n    console.error('One failed:', error);\n    // If any promise rejects, entire Promise.all rejects\n  });\n\n// Promise.race() - first settled (fulfilled OR rejected)\nconst promises2 = [\n  new Promise(resolve => setTimeout(() => resolve('Fast'), 100)),\n  new Promise(resolve => setTimeout(() => resolve('Slow'), 500)),\n  new Promise((_, reject) => setTimeout(() => reject('Error'), 50))\n];\n\nPromise.race(promises2)\n  .then(result => console.log('Race winner:', result))\n  .catch(error => console.log('Race loser:', error)); // 'Error' wins\n\n// Promise.allSettled() - waits for all to settle\nconst promises3 = [\n  Promise.resolve('Success 1'),\n  Promise.reject('Failure 1'),\n  Promise.resolve('Success 2')\n];\n\nPromise.allSettled(promises3)\n  .then(results => {\n    results.forEach((result, index) => {\n      if (result.status === 'fulfilled') {\n        console.log(`Promise ${index}:`, result.value);\n      } else {\n        console.log(`Promise ${index} failed:`, result.reason);\n      }\n    });\n  });\n\n// Promise.any() - first fulfilled (ignores rejections)\nconst promises4 = [\n  Promise.reject('Error 1'),\n  Promise.reject('Error 2'),\n  Promise.resolve('First success'),\n  Promise.resolve('Second success')\n];\n\nPromise.any(promises4)\n  .then(result => {\n    console.log('First success:', result); // 'First success'\n  })\n  .catch(error => {\n    console.error('All promises rejected:', error.errors);\n    // AggregateError containing all rejection reasons\n  });\n\n// Real-world example: timeout with Promise.race\nfunction fetchWithTimeout(url, timeout = 5000) {\n  const fetchPromise = fetch(url);\n  const timeoutPromise = new Promise((_, reject) => {\n    setTimeout(() => reject(new Error('Request timeout')), timeout);\n  });\n  \n  return Promise.race([fetchPromise, timeoutPromise]);\n}\n```",
