      userId: 'user_001',
      front: 'What are generators and how do they work with asynchronous code?',
      back: "Generators are functions that can be paused and resumed using yield. Combined with Promises, they enable async iteration patterns before async/await existed.\n\nExample:\n```javascript\n// Basic generator\nfunction* numberGenerator() {\n  yield 1;\n  yield 2;\n  yield 3;\n}\n\nconst gen = numberGenerator();\nconsole.log(gen.next().value); // 1\nconsole.log(gen.next().value); // 2\nconsole.log(gen.next().value); // 3\nconsole.log(gen.next().done);  // true\n\n// Async generator example\nasync function* asyncNumberGenerator() {\n  yield await Promise.resolve(1);\n  yield await Promise.resolve(2);\n  yield await Promise.resolve(3);\n}\n\n(async () => {\n  for await (const num of asyncNumberGenerator()) {\n    console.log(num); // 1, 2, 3\n  }\n})();\n\n// Generator with async operations (pre-async/await pattern)\nfunction* fetchUserGenerator(userId) {\n  const user = yield fetch(`/api/users/${userId}`).then(r => r.json());\n  const posts = yield fetch(`/api/users/${userId}/posts`).then(r => r.json());\n  return { user, posts };\n}\n\n// Runner function for generator\nfunction runGenerator(generator) {\n  const gen = generator();\n  \n  function handle(result) {\n    if (result.done) return Promise.resolve(result.value);\n    \n    return Promise.resolve(result.value)\n      .then(res => handle(gen.next(res)))\n      .catch(err => handle(gen.throw(err)));\n  }\n  \n  return handle(gen.next());\n}\n\n// Using the generator\nrunGenerator(() => fetchUserGenerator(1))\n  .then(data => console.log('Fetched:', data));\n\n// Real-world example: paginated API\nasync function* paginatedFetch(url) {\n  let nextUrl = url;\n  \n  while (nextUrl) {\n    const response = await fetch(nextUrl);\n    const data = await response.json();\n    \n    yield data.results;\n    nextUrl = data.next; // Assume API provides next page URL\n  }\n}\n\n// Usage\n(async () => {\n  const pages = paginatedFetch('https://api.example.com/items');\n  \n  for await (const items of pages) {\n    console.log('Page items:', items);\n    // Process each page\n  }\n})();\n```",
