      front: 'What is the Fetch API and how does it handle asynchrony?',
      back: "Fetch API is a modern replacement for XMLHttpRequest that returns Promises. It provides a cleaner, Promise-based interface for making HTTP requests.\n\nExample:\n```javascript\n// Basic fetch usage\nfetch('https://api.example.com/data')\n  .then(response => {\n    if (!response.ok) {\n      throw new Error(`HTTP error! status: ${response.status}`);\n    }\n    return response.json();\n  })\n  .then(data => {\n    console.log('Data:', data);\n  })\n  .catch(error => {\n    console.error('Fetch error:', error);\n  });\n\n// Fetch with async/await\nasync function getUserData(userId) {\n  try {\n    const response = await fetch(`https://api.example.com/users/${userId}`);\n    \n    if (response.status === 404) {\n      throw new Error('User not found');\n    }\n    \n    if (!response.ok) {\n      throw new Error(`HTTP ${response.status}`);\n    }\n    \n    return await response.json();\n  } catch (error) {\n    console.error('Failed to fetch user:', error);\n    throw error;\n  }\n}\n\n// Fetch with options\nasync function postData(url, data) {\n  const response = await fetch(url, {\n    method: 'POST',\n    headers: {\n      'Content-Type': 'application/json',\n      'Authorization': 'Bearer token123'\n    },\n    body: JSON.stringify(data),\n    mode: 'cors',\n    cache: 'no-cache',\n    credentials: 'same-origin'\n  });\n  \n  return response.json();\n}\n\n// Multiple parallel fetches\nasync function fetchMultiple(urls) {\n  const promises = urls.map(url => \n    fetch(url)\n      .then(response => response.json())\n      .catch(error => ({\n        url,\n        error: error.message\n      }))\n  );\n  \n  return Promise.all(promises);\n}\n\n// AbortController for canceling fetch\nasync function fetchWithTimeout(url, timeout = 5000) {\n  const controller = new AbortController();\n  const timeoutId = setTimeout(() => controller.abort(), timeout);\n  \n  try {\n    const response = await fetch(url, {\n      signal: controller.signal\n    });\n    clearTimeout(timeoutId);\n    return response.json();\n  } catch (error) {\n    if (error.name === 'AbortError') {\n      throw new Error('Request timeout');\n    }\n    throw error;\n  }\n}\n\n// Stream response (for large data)\nasync function processStream(url) {\n  const response = await fetch(url);\n  const reader = response.body.getReader();\n  \n  while (true) {\n    const {done, value} = await reader.read();\n    if (done) break;\n    console.log('Chunk:', new TextDecoder().decode(value));\n  }\n}\n```",
