      front: 'What are Web Workers and how do they enable concurrency?',
      back: "Web Workers run scripts in background threads, allowing CPU-intensive tasks without blocking the main thread. They communicate via message passing.\n\nExample:\n```javascript\n// main.js - Main thread\nconst worker = new Worker('worker.js');\n\n// Send message to worker\nworker.postMessage({\n  type: 'CALCULATE',\n  data: { numbers: [1, 2, 3, 4, 5] }\n});\n\n// Receive message from worker\nworker.onmessage = (event) => {\n  const { type, result } = event.data;\n  \n  if (type === 'CALCULATION_RESULT') {\n    console.log('Result from worker:', result);\n  }\n};\n\n// Handle errors\nworker.onerror = (error) => {\n  console.error('Worker error:', error);\n};\n\n// Terminate worker when done\n// worker.terminate();\n\n// worker.js - Worker thread\nself.onmessage = (event) => {\n  const { type, data } = event.data;\n  \n  if (type === 'CALCULATE') {\n    // CPU-intensive calculation\n    const result = data.numbers.reduce((sum, num) => sum + num, 0);\n    \n    // Send result back to main thread\n    self.postMessage({\n      type: 'CALCULATION_RESULT',\n      result\n    });\n  }\n};\n\n// Worker with multiple message types\n// main.js\nconst complexWorker = new Worker('complex-worker.js');\n\ncomplexWorker.postMessage({ type: 'START', data: 'initial' });\n\ncomplexWorker.onmessage = (event) => {\n  switch (event.data.type) {\n    case 'PROGRESS':\n      console.log(`Progress: ${event.data.progress}%`);\n      break;\n    case 'RESULT':\n      console.log('Final result:', event.data.result);\n      break;\n    case 'ERROR':\n      console.error('Worker error:', event.data.error);\n      break;\n  }\n};\n\n// complex-worker.js\nself.onmessage = async (event) => {\n  const { type, data } = event.data;\n  \n  if (type === 'START') {\n    try {\n      // Simulate long-running task with progress\n      for (let i = 0; i <= 100; i += 10) {\n        await new Promise(resolve => setTimeout(resolve, 100));\n        self.postMessage({ type: 'PROGRESS', progress: i });\n      }\n      \n      self.postMessage({ \n        type: 'RESULT', \n        result: 'Processing complete' \n      });\n    } catch (error) {\n      self.postMessage({ type: 'ERROR', error: error.message });\n    }\n  }\n};\n\n// Using Web Workers with Promises\nfunction runInWorker(task, data) {\n  return new Promise((resolve, reject) => {\n    const worker = new Worker(URL.createObjectURL(\n      new Blob([`\n        self.onmessage = ${task.toString()}\n      `], { type: 'application/javascript' })\n    ));\n    \n    worker.onmessage = (event) => {\n      resolve(event.data);\n      worker.terminate();\n    };\n    \n    worker.onerror = (error) => {\n      reject(error);\n      worker.terminate();\n    };\n    \n    worker.postMessage(data);\n  });\n}\n\n// Usage\nconst heavyTask = (event) => {\n  const data = event.data;\n  // Perform heavy computation\n  const result = data * 2;\n  self.postMessage(result);\n};\n\nrunInWorker(heavyTask, 42)\n  .then(result => console.log('Worker result:', result));\n```",
