      front:
        'What are setTimeout(), setInterval(), and requestAnimationFrame()?',
      back: "These are timer functions for scheduling code execution. setTimeout() runs once after delay, setInterval() repeats, requestAnimationFrame() syncs with browser repaints.\n\nExample:\n```javascript\n// setTimeout - execute once after delay\nconst timeoutId = setTimeout(() => {\n  console.log('This runs after 2 seconds');\n}, 2000);\n\n// Cancel before it runs\n// clearTimeout(timeoutId);\n\n// setInterval - execute repeatedly\nlet counter = 0;\nconst intervalId = setInterval(() => {\n  counter++;\n  console.log(`Tick ${counter}`);\n  \n  if (counter >= 5) {\n    clearInterval(intervalId);\n    console.log('Interval stopped');\n  }\n}, 1000);\n\n// requestAnimationFrame - for animations\nlet animationId;\nlet startTime;\n\nfunction animate(timestamp) {\n  if (!startTime) startTime = timestamp;\n  \n  const elapsed = timestamp - startTime;\n  const progress = Math.min(elapsed / 2000, 1); // 2 second animation\n  \n  // Update animation based on progress\n  console.log(`Animation progress: ${(progress * 100).toFixed(1)}%`);\n  \n  if (progress < 1) {\n    animationId = requestAnimationFrame(animate);\n  } else {\n    console.log('Animation complete');\n  }\n}\n\n// Start animation\n// animationId = requestAnimationFrame(animate);\n// Cancel: cancelAnimationFrame(animationId);\n\n// Real-world examples\n// Debouncing with setTimeout\nfunction debounce(func, delay) {\n  let timeoutId;\n  \n  return function(...args) {\n    clearTimeout(timeoutId);\n    timeoutId = setTimeout(() => {\n      func.apply(this, args);\n    }, delay);\n  };\n}\n\n// Usage\nconst searchInput = document.createElement('input');\nconst debouncedSearch = debounce((query) => {\n  console.log('Searching for:', query);\n}, 300);\n\n// searchInput.addEventListener('input', (e) => debouncedSearch(e.target.value));\n\n// Throttling with setInterval\nfunction throttle(func, limit) {\n  let inThrottle;\n  \n  return function(...args) {\n    if (!inThrottle) {\n      func.apply(this, args);\n      inThrottle = true;\n      setTimeout(() => inThrottle = false, limit);\n    }\n  };\n}\n\n// Polling with setInterval\nfunction pollApi(url, interval = 5000) {\n  const poll = async () => {\n    try {\n      const response = await fetch(url);\n      const data = await response.json();\n      console.log('Poll result:', data);\n    } catch (error) {\n      console.error('Poll error:', error);\n    }\n  };\n  \n  // Initial call\n  poll();\n  \n  // Then every interval\n  return setInterval(poll, interval);\n}\n\n// const pollId = pollApi('https://api.example.com/status');\n// clearInterval(pollId); // Stop polling\n\n// Accurate timing with performance.now()\nfunction measurePerformance() {\n  const start = performance.now();\n  \n  // Some expensive operation\n  for (let i = 0; i < 1000000; i++) {}\n  \n  const end = performance.now();\n  console.log(`Operation took ${(end - start).toFixed(2)}ms`);\n}\n```",
