      front:
        'What are Observables (RxJS) and how do they handle asynchronous streams?',
      back: "Observables represent push-based collections of multiple values over time. They're more powerful than Promises for handling streams of events or data.\n\nExample:\n```javascript\n// Basic Observable implementation (simplified)\nclass Observable {\n  constructor(subscribe) {\n    this._subscribe = subscribe;\n  }\n  \n  subscribe(observer) {\n    return this._subscribe(observer);\n  }\n  \n  pipe(...operators) {\n    return operators.reduce((obs, op) => op(obs), this);\n  }\n}\n\n// Creating an Observable\nconst intervalObservable = new Observable((observer) => {\n  let count = 0;\n  const intervalId = setInterval(() => {\n    observer.next(count++);\n    \n    if (count >= 5) {\n      observer.complete();\n      clearInterval(intervalId);\n    }\n  }, 1000);\n  \n  // Cleanup function\n  return () => {\n    clearInterval(intervalId);\n    console.log('Observable cleaned up');\n  };\n});\n\n// Subscribing to the Observable\nconst subscription = intervalObservable.subscribe({\n  next: (value) => console.log('Received:', value),\n  error: (err) => console.error('Error:', err),\n  complete: () => console.log('Observable completed')\n});\n\n// Unsubscribe after 3 seconds\nsetTimeout(() => {\n  subscription.unsubscribe();\n  console.log('Unsubscribed');\n}, 3000);\n\n// Observable operators (simplified)\nfunction map(transform) {\n  return (observable) => new Observable((observer) => {\n    return observable.subscribe({\n      next: (value) => observer.next(transform(value)),\n      error: (err) => observer.error(err),\n      complete: () => observer.complete()\n    });\n  });\n}\n\nfunction filter(predicate) {\n  return (observable) => new Observable((observer) => {\n    return observable.subscribe({\n      next: (value) => {\n        if (predicate(value)) {\n          observer.next(value);\n        }\n      },\n      error: (err) => observer.error(err),\n      complete: () => observer.complete()\n    });\n  });\n}\n\n// Using operators\nintervalObservable\n  .pipe(\n    map(x => x * 2),\n    filter(x => x % 3 === 0)\n  )\n  .subscribe({\n    next: (value) => console.log('Transformed:', value)\n  });\n\n// Real-world example: DOM events as Observable\nfunction fromEvent(element, eventName) {\n  return new Observable((observer) => {\n    const handler = (event) => observer.next(event);\n    element.addEventListener(eventName, handler);\n    \n    return () => {\n      element.removeEventListener(eventName, handler);\n    };\n  });\n}\n\n// Usage with debounce\nconst button = document.createElement('button');\nconst click$ = fromEvent(button, 'click');\n\nclick$\n  .pipe(\n    // Simulated debounce operator\n    (observable) => new Observable((observer) => {\n      let timeoutId;\n      return observable.subscribe({\n        next: (value) => {\n          clearTimeout(timeoutId);\n          timeoutId = setTimeout(() => observer.next(value), 300);\n        }\n      });\n    })\n  )\n  .subscribe(() => console.log('Clicked!'));\n\n// Converting Promise to Observable\nfunction fromPromise(promise) {\n  return new Observable((observer) => {\n    promise\n      .then(value => {\n        observer.next(value);\n        observer.complete();\n      })\n      .catch(error => observer.error(error));\n  });\n}\n```",
