      front: 'How do async iterators and for-await-of loops work?',
      back: "Async iterators allow asynchronous iteration over data. for-await-of loops iterate over async iterables, awaiting each value before continuing.\n\nExample:\n```javascript\n// Async iterator protocol\nconst asyncIterable = {\n  [Symbol.asyncIterator]() {\n    let i = 0;\n    \n    return {\n      async next() {\n        await new Promise(resolve => setTimeout(resolve, 100));\n        \n        if (i < 5) {\n          return { value: i++, done: false };\n        }\n        \n        return { done: true };\n      },\n      \n      async return() {\n        console.log('Cleaning up async iterator');\n        return { done: true };\n      }\n    };\n  }\n};\n\n// Using for-await-of\n(async () => {\n  try {\n    for await (const value of asyncIterable) {\n      console.log('Async value:', value);\n      \n      if (value === 2) {\n        break; // Triggers return() method\n      }\n    }\n  } catch (error) {\n    console.error('Iteration error:', error);\n  }\n})();\n\n// Async generator function\nasync function* asyncGenerator() {\n  yield await Promise.resolve(1);\n  yield await Promise.resolve(2);\n  yield await Promise.resolve(3);\n}\n\n// Consuming async generator\n(async () => {\n  const asyncGen = asyncGenerator();\n  \n  console.log(await asyncGen.next()); // {value: 1, done: false}\n  console.log(await asyncGen.next()); // {value: 2, done: false}\n  console.log(await asyncGen.next()); // {value: 3, done: false}\n  console.log(await asyncGen.next()); // {value: undefined, done: true}\n})();\n\n// Real-world example: Paginated API\nasync function* paginatedResults(url) {\n  let nextUrl = url;\n  \n  while (nextUrl) {\n    const response = await fetch(nextUrl);\n    const data = await response.json();\n    \n    yield data.items;\n    nextUrl = data.nextPage;\n  }\n}\n\n// Usage\n(async () => {\n  for await (const pageItems of paginatedResults('/api/data')) {\n    console.log('Processing page:', pageItems);\n    // Process each page of items\n  }\n})();\n\n// Async iterator from ReadableStream\nasync function* streamToAsyncIterator(stream) {\n  const reader = stream.getReader();\n  \n  try {\n    while (true) {\n      const { done, value } = await reader.read();\n      \n      if (done) {\n        return;\n      }\n      \n      yield value;\n    }\n  } finally {\n    reader.releaseLock();\n  }\n}\n\n// Usage with fetch stream\n(async () => {\n  const response = await fetch('https://api.example.com/large-data');\n  const stream = response.body;\n  \n  for await (const chunk of streamToAsyncIterator(stream)) {\n    console.log('Received chunk:', chunk);\n  }\n})();\n\n// Creating custom async iterable\nclass RateLimitedFetcher {\n  constructor(urls, delay = 1000) {\n    this.urls = urls;\n    this.delay = delay;\n  }\n  \n  async *[Symbol.asyncIterator]() {\n    for (const url of this.urls) {\n      await new Promise(resolve => setTimeout(resolve, this.delay));\n      \n      try {\n        const response = await fetch(url);\n        const data = await response.json();\n        yield data;\n      } catch (error) {\n        yield { error: error.message, url };\n      }\n    }\n  }\n}\n\n// Usage\nconst fetcher = new RateLimitedFetcher([\n  'https://api.example.com/data1',\n  'https://api.example.com/data2'\n], 2000);\n\n(async () => {\n  for await (const result of fetcher) {\n    console.log('Fetched:', result);\n  }\n})();\n```",
