      front: 'What are error handling patterns in async JavaScript?',
      back: "Proper error handling in async code requires different patterns than synchronous code, including try/catch with async/await, Promise.catch(), and error boundaries.\n\nExample:\n```javascript\n// 1. Try/catch with async/await\nasync function fetchWithRetry(url, retries = 3) {\n  for (let i = 0; i < retries; i++) {\n    try {\n      const response = await fetch(url);\n      \n      if (!response.ok) {\n        throw new Error(`HTTP ${response.status}`);\n      }\n      \n      return await response.json();\n    } catch (error) {\n      console.log(`Attempt ${i + 1} failed:`, error.message);\n      \n      if (i === retries - 1) {\n        throw new Error(`Failed after ${retries} attempts: ${error.message}`);\n      }\n      \n      // Wait before retry (exponential backoff)\n      await new Promise(resolve => setTimeout(resolve, 1000 * Math.pow(2, i)));\n    }\n  }\n}\n\n// 2. Promise.catch() chaining\nfunction loadUserData(userId) {\n  return fetch(`/api/users/${userId}`)\n    .then(response => {\n      if (!response.ok) {\n        throw new Error('User not found');\n      }\n      return response.json();\n    })\n    .then(user => fetch(`/api/posts/${user.id}`))\n    .then(response => response.json())\n    .catch(error => {\n      console.error('Failed to load user data:', error);\n      // Return default value\n      return { user: null, posts: [] };\n    })\n    .finally(() => {\n      console.log('User data loading completed');\n    });\n}\n\n// 3. Error boundaries with async functions\nasync function safeAsyncOperation(operation, fallbackValue) {\n  try {\n    return await operation();\n  } catch (error) {\n    console.error('Operation failed:', error);\n    return fallbackValue;\n  }\n}\n\n// Usage\nconst result = await safeAsyncOperation(\n  () => fetchWithRetry('https://api.example.com/data'),\n  { data: 'default' }\n);\n\n// 4. Promise error handling utilities\nfunction timeout(promise, ms) {\n  return Promise.race([\n    promise,\n    new Promise((_, reject) => {\n      setTimeout(() => reject(new Error(`Timeout after ${ms}ms`)), ms);\n    })\n  ]);\n}\n\n// Usage with error handling\ntimeout(fetch('https://api.example.com/slow'), 5000)\n  .then(response => response.json())\n  .catch(error => {\n    if (error.message.includes('Timeout')) {\n      console.log('Request timed out');\n      return { data: 'timeout_fallback' };\n    }\n    throw error;\n  });\n\n// 5. Aggregate error handling\nasync function fetchMultipleWithErrors(urls) {\n  const promises = urls.map(url => \n    fetch(url)\n      .then(response => response.json())\n      .catch(error => ({\n        url,\n        error: error.message,\n        success: false\n      }))\n  );\n  \n  const results = await Promise.allSettled(promises);\n  \n  const successful = [];\n  const failed = [];\n  \n  for (const result of results) {\n    if (result.status === 'fulfilled' && !result.value.error) {\n      successful.push(result.value);\n    } else {\n      failed.push(result.reason || result.value);\n    }\n  }\n  \n  return { successful, failed };\n}\n\n// 6. Global error handling\n// Unhandled Promise rejections\nprocess.on('unhandledRejection', (reason, promise) => {\n  console.error('Unhandled Rejection at:', promise, 'reason:', reason);\n  // Application specific logging, throwing error, or exit logic\n});\n\n// Browser: window.addEventListener('unhandledrejection', event => {\n//   console.error('Unhandled rejection:', event.reason);\n// });\n\n// 7. Error wrapping for better context\nclass ApiError extends Error {\n  constructor(message, url, status) {\n    super(message);\n    this.name = 'ApiError';\n    this.url = url;\n    this.status = status;\n  }\n}\n\nasync function fetchApi(url) {\n  const response = await fetch(url);\n  \n  if (!response.ok) {\n    throw new ApiError(\n      `API request failed: ${response.statusText}`,\n      url,\n      response.status\n    );\n  }\n  \n  return response.json();\n}\n\n// Usage with specific error handling\nfetchApi('https://api.example.com/data')\n  .catch(error => {\n    if (error instanceof ApiError) {\n      console.error(`API Error (${error.status}):`, error.message);\n      // Handle API errors specifically\n    } else {\n      console.error('Unknown error:', error);\n    }\n  });\n```",
