      front: 'What is the queueMicrotask() API and when should you use it?',
      back: "queueMicrotask() schedules a microtask to run after the current task completes but before control is returned to the event loop. It's useful for ensuring code runs in a clean state.\n\nExample:\n```javascript\n// Basic queueMicrotask usage\nconsole.log('Start');\n\nqueueMicrotask(() => {\n  console.log('Microtask 1');\n});\n\nqueueMicrotask(() => {\n  console.log('Microtask 2');\n});\n\nconsole.log('End');\n\n// Output:\n// Start\n// End\n// Microtask 1\n// Microtask 2\n\n// Comparison with Promises\nconsole.log('Script start');\n\nPromise.resolve().then(() => {\n  console.log('Promise 1');\n});\n\nqueueMicrotask(() => {\n  console.log('queueMicrotask 1');\n});\n\nPromise.resolve().then(() => {\n  console.log('Promise 2');\n});\n\nconsole.log('Script end');\n\n// Output:\n// Script start\n// Script end\n// Promise 1\n// queueMicrotask 1\n// Promise 2\n// (All microtasks execute in order of queueing)\n\n// Use case: Ensuring cleanup happens at microtask timing\nfunction processData(data) {\n  // Store current state\n  const previousState = getCurrentState();\n  \n  try {\n    // Process data\n    const result = expensiveOperation(data);\n    return result;\n  } finally {\n    // Schedule cleanup as microtask\n    queueMicrotask(() => {\n      restoreState(previousState);\n      console.log('Cleanup completed');\n    });\n  }\n}\n\n// Use case: Batching updates\nlet updateQueue = [];\nlet isUpdateScheduled = false;\n\nfunction scheduleUpdate(updateFn) {\n  updateQueue.push(updateFn);\n  \n  if (!isUpdateScheduled) {\n    isUpdateScheduled = true;\n    \n    queueMicrotask(() => {\n      isUpdateScheduled = false;\n      const queue = updateQueue;\n      updateQueue = [];\n      \n      queue.forEach(fn => {\n        try {\n          fn();\n        } catch (error) {\n          console.error('Update error:', error);\n        }\n      });\n    });\n  }\n}\n\n// Usage\nscheduleUpdate(() => console.log('Update 1'));\nscheduleUpdate(() => console.log('Update 2'));\nconsole.log('Updates scheduled');\n\n// Use case: Avoiding stack overflow with recursion\nfunction recursiveOperation(count) {\n  if (count <= 0) return;\n  \n  // Do some work\n  console.log(`Processing ${count}`);\n  \n  // Schedule next iteration as microtask\n  queueMicrotask(() => {\n    recursiveOperation(count - 1);\n  });\n}\n\n// This won't cause stack overflow\n// recursiveOperation(1000);\n\n// Comparison with setTimeout and Promise\nconsole.log('A');\n\nsetTimeout(() => console.log('B'), 0);\n\nPromise.resolve().then(() => {\n  console.log('C');\n  queueMicrotask(() => console.log('D'));\n});\n\nqueueMicrotask(() => console.log('E'));\n\nPromise.resolve().then(() => console.log('F'));\n\nconsole.log('G');\n\n// Output:\n// A\n// G\n// C\n// E\n// D\n// F\n// B\n\n// Explanation:\n// 1. Synchronous: A, G\n// 2. Microtasks (in queue order): C, E (from first Promise), D (queued by C), F\n// 3. Macrotask: B (setTimeout)\n\n// Real-world example: React-like batched updates\nclass Component {\n  constructor() {\n    this.state = { count: 0 };\n    this.updatePending = false;\n  }\n  \n  setState(newState) {\n    Object.assign(this.state, newState);\n    \n    if (!this.updatePending) {\n      this.updatePending = true;\n      \n      queueMicrotask(() => {\n        this.updatePending = false;\n        this.performUpdate();\n      });\n    }\n  }\n  \n  performUpdate() {\n    console.log('Component updated with state:', this.state);\n    // Render logic here\n  }\n}\n\nconst comp = new Component();\ncomp.setState({ count: 1 });\ncomp.setState({ count: 2 });\ncomp.setState({ count: 3 });\nconsole.log('State updates scheduled');\n\n// Only one performUpdate() will run, with final state {count: 3}\n```",
