      front: 'What are async patterns for data fetching and state management?',
      back: "Common async patterns include loading states, error boundaries, race condition prevention, caching, and optimistic updates for better UX.\n\nExample:\n```javascript\n// 1. Loading state pattern\nasync function withLoading(operation, loadingCallback) {\n  loadingCallback(true);\n  \n  try {\n    const result = await operation();\n    return result;\n  } finally {\n    loadingCallback(false);\n  }\n}\n\n// Usage\nlet isLoading = false;\n\nwithLoading(\n  () => fetch('https://api.example.com/data').then(r => r.json()),\n  (loading) => { isLoading = loading; }\n).then(data => {\n  console.log('Data loaded:', data);\n});\n\n// 2. Race condition prevention with cancellation\nfunction createCancellableFetch(url) {\n  const controller = new AbortController();\n  \n  const promise = fetch(url, {\n    signal: controller.signal\n  }).then(response => response.json());\n  \n  promise.cancel = () => controller.abort();\n  \n  return promise;\n}\n\n// Usage in component\nlet currentFetch;\n\nfunction loadData() {\n  // Cancel previous fetch if still pending\n  if (currentFetch && currentFetch.cancel) {\n    currentFetch.cancel();\n  }\n  \n  currentFetch = createCancellableFetch('/api/data');\n  return currentFetch;\n}\n\n// 3. Optimistic updates\nasync function updateItem(itemId, newData) {\n  // Store current state for rollback\n  const previousData = await getItem(itemId);\n  \n  // Optimistically update UI\n  updateUI(itemId, newData);\n  \n  try {\n    // Send update to server\n    const response = await fetch(`/api/items/${itemId}`, {\n      method: 'PUT',\n      body: JSON.stringify(newData)\n    });\n    \n    if (!response.ok) {\n      throw new Error('Update failed');\n    }\n    \n    const actualData = await response.json();\n    \n    // Sync UI with actual server response\n    updateUI(itemId, actualData);\n    \n    return actualData;\n  } catch (error) {\n    // Rollback on error\n    updateUI(itemId, previousData);\n    showError('Update failed, rolled back');\n    throw error;\n  }\n}\n\n// 4. Caching pattern\nconst cache = new Map();\n\nasync function fetchWithCache(url, options = {}) {\n  const { ttl = 60000, forceRefresh = false } = options;\n  const now = Date.now();\n  \n  // Check cache\n  if (!forceRefresh && cache.has(url)) {\n    const { data, timestamp } = cache.get(url);\n    \n    if (now - timestamp < ttl) {\n      console.log('Returning cached data for:', url);\n      return data;\n    }\n  }\n  \n  // Fetch fresh data\n  console.log('Fetching fresh data for:', url);\n  const response = await fetch(url);\n  const data = await response.json();\n  \n  // Update cache\n  cache.set(url, { data, timestamp: now });\n  \n  return data;\n}\n\n// 5. Retry with exponential backoff\nasync function fetchWithExponentialBackoff(url, maxRetries = 3) {\n  for (let attempt = 0; attempt <= maxRetries; attempt++) {\n    try {\n      const response = await fetch(url);\n      \n      if (!response.ok) {\n        throw new Error(`HTTP ${response.status}`);\n      }\n      \n      return await response.json();\n    } catch (error) {\n      if (attempt === maxRetries) {\n        throw error;\n      }\n      \n      // Calculate delay: 1s, 2s, 4s, 8s...\n      const delay = 1000 * Math.pow(2, attempt);\n      console.log(`Retry ${attempt + 1} in ${delay}ms`);\n      \n      await new Promise(resolve => setTimeout(resolve, delay));\n    }\n  }\n}\n\n// 6. Parallel fetching with limits\nclass ConcurrentFetcher {\n  constructor(maxConcurrent = 3) {\n    this.maxConcurrent = maxConcurrent;\n    this.queue = [];\n    this.active = 0;\n  }\n  \n  async fetch(url) {\n    return new Promise((resolve, reject) => {\n      this.queue.push({ url, resolve, reject });\n      this.processQueue();\n    });\n  }\n  \n  async processQueue() {\n    if (this.active >= this.maxConcurrent || this.queue.length === 0) {\n      return;\n    }\n    \n    this.active++;\n    const { url, resolve, reject } = this.queue.shift();\n    \n    try {\n      const response = await fetch(url);\n      const data = await response.json();\n      resolve(data);\n    } catch (error) {\n      reject(error);\n    } finally {\n      this.active--;\n      this.processQueue();\n    }\n  }\n}\n\n// Usage\nconst fetcher = new ConcurrentFetcher(2);\nconst urls = ['/api/1', '/api/2', '/api/3', '/api/4'];\n\nPromise.all(urls.map(url => fetcher.fetch(url)))\n  .then(results => console.log('All fetched:', results));\n\n// 7. Debounced search\nfunction createSearch() {\n  let timeoutId;\n  let controller;\n  \n  return async function search(query) {\n    // Cancel previous request and timeout\n    if (timeoutId) clearTimeout(timeoutId);\n    if (controller) controller.abort();\n    \n    if (!query.trim()) {\n      return [];\n    }\n    \n    return new Promise((resolve) => {\n      timeoutId = setTimeout(async () => {\n        controller = new AbortController();\n        \n        try {\n          const response = await fetch(`/api/search?q=${query}`, {\n            signal: controller.signal\n          });\n          const results = await response.json();\n          resolve(results);\n        } catch (error) {\n          if (error.name !== 'AbortError') {\n            console.error('Search error:', error);\n            resolve([]);\n          }\n        }\n      }, 300); // 300ms debounce\n    });\n  };\n}\n\nconst performSearch = createSearch();\n\n// Usage in input event handler\n// input.addEventListener('input', async (e) => {\n//   const results = await performSearch(e.target.value);\n//   displayResults(results);\n// });\n```",
