      front: 'What are Node.js specific async patterns and utilities?',
      back: "Node.js provides additional async utilities like streams, child processes, file system operations with Promises, and the events module for event-driven async patterns.\n\nExample:\n```javascript\n// Note: These examples assume Node.js environment\n\n// 1. Promisified fs module\nimport { promises as fs } from 'fs'; // Node.js 10+\n\nasync function readAndProcessFile(filePath) {\n  try {\n    const data = await fs.readFile(filePath, 'utf8');\n    const processed = processData(data);\n    await fs.writeFile(`${filePath}.processed`, processed);\n    console.log('File processed successfully');\n  } catch (error) {\n    console.error('File operation failed:', error);\n  }\n}\n\n// 2. Streams with async iteration\nimport { createReadStream } from 'fs';\nimport { pipeline } from 'stream/promises';\n\nasync function processLargeFile(filePath) {\n  const readStream = createReadStream(filePath, { encoding: 'utf8' });\n  \n  // Using async iteration with streams\n  for await (const chunk of readStream) {\n    console.log('Processing chunk:', chunk.length, 'bytes');\n    // Process each chunk\n  }\n  \n  console.log('File processing complete');\n}\n\n// 3. Child processes with Promises\nimport { exec, spawn } from 'child_process';\nimport { promisify } from 'util';\n\nconst execAsync = promisify(exec);\n\nasync function runCommand(command) {\n  try {\n    const { stdout, stderr } = await execAsync(command);\n    \n    if (stderr) {\n      console.warn('Command stderr:', stderr);\n    }\n    \n    return stdout;\n  } catch (error) {\n    console.error('Command failed:', error);\n    throw error;\n  }\n}\n\n// Usage\n// const result = await runCommand('ls -la');\n\n// 4. EventEmitter with Promises\nimport { EventEmitter } from 'events';\n\nclass AsyncEventEmitter extends EventEmitter {\n  emitAsync(event, ...args) {\n    const listeners = this.listeners(event);\n    \n    if (listeners.length === 0) {\n      return Promise.resolve();\n    }\n    \n    return Promise.all(\n      listeners.map(listener => {\n        try {\n          return Promise.resolve(listener(...args));\n        } catch (error) {\n          return Promise.reject(error);\n        }\n      })\n    );\n  }\n}\n\n// Usage\nconst emitter = new AsyncEventEmitter();\n\nemitter.on('process', async (data) => {\n  await new Promise(resolve => setTimeout(resolve, 100));\n  console.log('Processed:', data);\n  return 'done';\n});\n\nemitter.emitAsync('process', 'test data')\n  .then(results => console.log('All listeners completed:', results));\n\n// 5. util.promisify for callback-based APIs\nimport { promisify } from 'util';\nimport { readFile } from 'fs';\n\nconst readFileAsync = promisify(readFile);\n\nasync function readMultipleFiles(filePaths) {\n  const promises = filePaths.map(filePath => \n    readFileAsync(filePath, 'utf8')\n  );\n  \n  return Promise.all(promises);\n}\n\n// 6. Timers with Promises\nfunction delay(ms) {\n  return new Promise(resolve => setTimeout(resolve, ms));\n}\n\nasync function timedOperation() {\n  console.log('Starting operation...');\n  await delay(1000);\n  console.log('Operation completed after 1 second');\n}\n\n// 7. Async resource pooling\nclass ConnectionPool {\n  constructor(createConnection, maxConnections = 5) {\n    this.createConnection = createConnection;\n    this.maxConnections = maxConnections;\n    this.pool = [];\n    this.waiting = [];\n  }\n  \n  async getConnection() {\n    // Return existing available connection\n    if (this.pool.length > 0) {\n      return this.pool.pop();\n    }\n    \n    // Create new connection if under limit\n    if (this.pool.length + this.waiting.length < this.maxConnections) {\n      return this.createConnection();\n    }\n    \n    // Wait for connection to become available\n    return new Promise((resolve) => {\n      this.waiting.push(resolve);\n    });\n  }\n  \n  releaseConnection(connection) {\n    if (this.waiting.length > 0) {\n      const resolve = this.waiting.shift();\n      resolve(connection);\n    } else {\n      this.pool.push(connection);\n    }\n  }\n}\n\n// Usage\nconst pool = new ConnectionPool(async () => {\n  console.log('Creating new connection');\n  return { connected: true, id: Math.random() };\n});\n\nasync function useConnection() {\n  const conn = await pool.getConnection();\n  \n  try {\n    // Use connection\n    console.log('Using connection:', conn.id);\n    await delay(500); // Simulate work\n  } finally {\n    pool.releaseConnection(conn);\n  }\n}\n\n// 8. Async queue for task processing\nimport { EventEmitter } from 'events';\n\nclass AsyncQueue extends EventEmitter {\n  constructor(concurrency = 1) {\n    super();\n    this.concurrency = concurrency;\n    this.running = 0;\n    this.queue = [];\n  }\n  \n  enqueue(task) {\n    return new Promise((resolve, reject) => {\n      this.queue.push({ task, resolve, reject });\n      this.process();\n    });\n  }\n  \n  async process() {\n    if (this.running >= this.concurrency || this.queue.length === 0) {\n      return;\n    }\n    \n    this.running++;\n    const { task, resolve, reject } = this.queue.shift();\n    \n    try {\n      const result = await task();\n      resolve(result);\n    } catch (error) {\n      reject(error);\n    } finally {\n      this.running--;\n      this.process();\n      \n      if (this.running === 0 && this.queue.length === 0) {\n        this.emit('drain');\n      }\n    }\n  }\n}\n\n// Usage\nconst queue = new AsyncQueue(2); // Process 2 tasks concurrently\n\nqueue.on('drain', () => {\n  console.log('All tasks completed');\n});\n\n// Enqueue tasks\nfor (let i = 1; i <= 5; i++) {\n  queue.enqueue(async () => {\n    console.log(`Processing task ${i}`);\n    await delay(1000);\n    return `Result ${i}`;\n  }).then(result => {\n    console.log(`Task completed: ${result}`);\n  });\n}\n```",
